contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address spender, uint256 amount) public {
        require(spender != address(0));
        require(amount != 0);

        bool ok1 = c.approve(spender, amount); if (__ESBMC_reverted()) return;
        bool ok2 = c.approve(spender, 0); if (__ESBMC_reverted()) return;

        assert(ok1 && ok2 && c.allowance(address(this), spender) == 0);
    }

    receive() external payable {}
}

